<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { listTemplates } from '../api/templates'
import { listChangeLogs, pageReports, type ReportChangeLog, type ReportPage } from '../api/reports'
import { cancelChangeRequest, createChangeRequest, listChangeRequests, type ChangeRequest } from '../api/changeRequests'
import { listTaskReminders, type TaskReminder } from '../api/tasks'
import type { Report, Template } from '../types'

const templates = ref<Template[]>([]); const records = ref<Report[]>([]); const requests = ref<ChangeRequest[]>([]); const reminders = ref<TaskReminder[]>([]); const page = ref(0); const size = ref(10); const totalPages = ref(0); const loading = ref(false); const error = ref(''); const message = ref('')
const selected = ref<Report | null>(null); const editData = ref<Record<string, string>>({}); const reason = ref(''); const logsFor = ref<Report | null>(null); const logs = ref<ReportChangeLog[]>([])
const columns = computed(() => templates.value.find(item => String(item.id) === String(selected.value?.templateId))?.columns || [])
function dataOf(value: Report['data']) { return typeof value === 'object' && value ? value as Record<string, unknown> : {} }
function text(e: unknown) { return e instanceof Error ? e.message : '操作失败' }
function date(value?: string) { return value?.replace('T', ' ').replace(/\.\d+$/, '') || '-' }
function requestsOf(record: Report) { return requests.value.filter(item => String(item.reportId) === String(record.id)).sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || ''))) }
function requestOf(record: Report) { return requestsOf(record).find(item => item.status === 'PENDING') }
function latestRequestOf(record: Report) { return requestsOf(record)[0] }
function requestStatus(record: Report) { const item = latestRequestOf(record); if (!item) return '-'; if (item.status === 'PENDING') return '待审批'; if (item.status === 'REJECTED') return `已退回：${item.reviewComment || '请修改后重新提交'}`; if (item.status === 'APPROVED') return '已通过'; return item.status }
async function load() { loading.value = true; try { const result: ReportPage = await pageReports({ page: page.value, size: size.value }); records.value = result.records; totalPages.value = result.totalPages; [requests.value, reminders.value] = await Promise.all([listChangeRequests(), listTaskReminders()]) } catch (e) { error.value = text(e) } finally { loading.value = false } }
function open(record: Report) { selected.value = record; editData.value = Object.fromEntries(Object.entries(dataOf(record.data)).map(([key, value]) => [key, String(value ?? '')])); reason.value = '' }
function close() { selected.value = null }
async function submit() { if (!selected.value) return; if (!reason.value.trim()) { error.value = '请填写修改原因'; return }; try { await createChangeRequest(selected.value.id, { data: editData.value, reason: reason.value.trim(), baseUpdatedAt: selected.value.updatedAt || '' }); message.value = '修改申请已提交，等待审批'; close(); await load() } catch (e) { error.value = text(e) } }
async function cancel(request: ChangeRequest) { try { await cancelChangeRequest(request.id); message.value = '修改申请已撤回'; await load() } catch (e) { error.value = text(e) } }
async function openLogs(record: Report) { try { logs.value = await listChangeLogs(record.id); logsFor.value = record } catch (e) { error.value = text(e) } }
onMounted(async () => { templates.value = await listTemplates(); await load() })
</script>

<template><section><div class="page-heading"><div><h1>我的填报</h1><p>查看本人填报记录，并对已提交记录申请修改。</p></div><button class="secondary" @click="load">刷新</button></div><div v-if="message" class="notice success">{{ message }}</div><div v-if="error" class="notice error">{{ error }}</div><div class="table-wrap"><table><thead><tr><th>任务</th><th>模板</th><th>提交时间</th><th>状态</th><th>修改申请</th><th class="fixed-action">操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="muted">加载中...</td></tr><tr v-else-if="!records.length"><td colspan="6" class="muted">暂无填报数据。</td></tr><tr v-for="record in records" :key="record.id"><td>{{ record.taskName || '-' }}</td><td>{{ record.templateName }}</td><td>{{ date(record.updatedAt) }}</td><td>{{ record.status }}</td><td><template v-if="requestOf(record)"><span class="status">待审批</span><button class="text-button" @click="cancel(requestOf(record)!)">撤回</button></template><span v-else>{{ requestStatus(record) }}</span></td><td class="fixed-action"><button class="text-button" :disabled="Boolean(requestOf(record))" @click="open(record)">{{ latestRequestOf(record)?.status === 'REJECTED' ? '重新提交' : '申请修改' }}</button><button class="text-button" @click="openLogs(record)">日志</button></td></tr></tbody></table></div><footer class="detail-pagination"><button class="secondary" :disabled="page===0" @click="page--;load()">上一页</button><span>第 {{ page + 1 }} / {{ Math.max(1, totalPages) }} 页</span><button class="secondary" :disabled="page+1>=totalPages" @click="page++;load()">下一页</button></footer><div v-if="selected" class="modal-backdrop" @click.self="close"><section class="detail-modal"><header class="detail-modal-header"><div><h2>申请修改</h2><p>{{ selected.taskName || selected.templateName }}</p></div><button class="text-button" @click="close">关闭</button></header><div class="detail-table-scroll"><table class="detail-report-table"><thead><tr><th v-for="column in columns" :key="column.key">{{ column.label }}</th></tr></thead><tbody><tr><td v-for="column in columns" :key="column.key"><textarea v-if="column.type==='textarea'" v-model="editData[column.key]" rows="1" /><input v-else v-model="editData[column.key]" :type="column.type==='number'?'number':column.type==='date'?'date':column.type==='month'?'month':'text'" /></td></tr></tbody></table></div><div class="detail-toolbar"><label>修改原因<input v-model.trim="reason" maxlength="500" /></label><button class="primary" @click="submit">提交申请</button></div></section></div><div v-if="logsFor" class="modal-backdrop" @click.self="logsFor = null"><section class="detail-modal"><header class="detail-modal-header"><div><h2>操作日志</h2><p>{{ logsFor.taskName || logsFor.templateName }}</p></div><button class="text-button" @click="logsFor = null">关闭</button></header><div class="detail-table-scroll"><table><thead><tr><th>操作人</th><th>动作</th><th>原因</th><th>时间</th></tr></thead><tbody><tr v-if="!logs.length"><td colspan="4" class="muted">暂无日志。</td></tr><tr v-for="log in logs" :key="log.id"><td>{{ log.actorName }}</td><td>{{ log.action }}</td><td>{{ log.reason || '-' }}</td><td>{{ date(log.createdAt) }}</td></tr></tbody></table></div></section></div></section></template>
